def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for axis in (0, 1):  # 0: repeat rows; 1: repeat columns
        length = h if axis == 0 else w
        cross = w if axis == 0 else h
        lines = []
        for i in range(length):
            vals = [grid[i][j] for j in range(cross)] if axis == 0 else [grid[j][i] for j in range(cross)]
            if len(set(vals)) == 1 and vals[0] != bg:
                lines.append(i)

        if not lines:
            continue

        if len(lines) >= 2:
            gaps = [b - a for a, b in zip(lines, lines[1:])]
            period = min(gaps)
        else:
            period = lines[0] + 1

        if period <= 0:
            continue

        # Gather non-background cells by their position within the repeating period,
        # then copy them to every matching position.
        marks = {}
        for i in range(length):
            for j in range(cross):
                val = grid[i][j] if axis == 0 else grid[j][i]
                if val != bg:
                    marks.setdefault((i % period, j), val)

        for i in range(length):
            for j in range(cross):
                val = marks.get((i % period, j))
                if val is not None:
                    if axis == 0:
                        out[i][j] = val
                    else:
                        out[j][i] = val

    return out
